import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line1 = br.readLine().split("\\s+");
        int n = Integer.parseInt(line1[0]);
        long m = Long.parseLong(line1[1]);

        long[] a = new long[n];
        String[] line2 = br.readLine().split("\\s+");
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(line2[i]);
        }

        // Split the array into two halves
        int mid = n / 2;
        int n1 = mid;
        int n2 = n - mid;

        // Generate all possible subset sums for the first half
        long[] sums1 = new long[1 << n1];
        for (int mask = 0; mask < (1 << n1); mask++) {
            long sum = 0;
            for (int i = 0; i < n1; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum = (sum + a[i]) % m;
                }
            }
            sums1[mask] = sum;
        }

        // Sort the first half sums
        Arrays.sort(sums1);

        long maxMod = 0;

        // Iterate over all possible subset sums for the second half
        for (int mask = 0; mask < (1 << n2); mask++) {
            long sum2 = 0;
            for (int i = 0; i < n2; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum2 = (sum2 + a[mid + i]) % m;
                }
            }

            // We want to maximize (sum1 + sum2) % m
            // Let S = sum2. We want to find sum1 such that (sum1 + S) % m is maximized.
            // This is equivalent to finding sum1 such that sum1 + S is as close to m-1 as possible without exceeding it,
            // or sum1 + S >= m and (sum1 + S) % m is as close to m-1 as possible.

            // Case 1: sum1 + sum2 < m. Maximize sum1 + sum2.
            // We need sum1 <= m - 1 - sum2.
            // Find the largest sum1 in sums1 that is <= m - 1 - sum2.
            long target1 = (m - 1 - sum2) % m;
            if (target1 < 0) target1 += m; // Though m-1-sum2 is always >= -m+1, so if sum2 > m-1 it's not possible, but sum2 < m.
            // Actually, m-1-sum2 is in range [0, m-1] since sum2 in [0, m-1].

            int idx1 = Arrays.binarySearch(sums1, target1);
            if (idx1 < 0) {
                idx1 = -idx1 - 1; // Insertion point
                idx1--; // Previous element
            }
            if (idx1 >= 0) {
                long candidate = (sums1[idx1] + sum2) % m;
                if (candidate > maxMod) {
                    maxMod = candidate;
                }
            }

            // Case 2: sum1 + sum2 >= m. Maximize (sum1 + sum2) % m.
            // This is equivalent to minimizing sum1 + sum2 - m, i.e., minimizing sum1 + sum2 subject to sum1 + sum2 >= m.
            // Or simply, we want sum1 such that sum1 >= m - sum2.
            // Let's find the smallest sum1 >= m - sum2.
            long target2 = m - sum2;
            if (target2 >= m) {
                // This means sum2 == 0, so we need sum1 >= m, which is impossible since sum1 < m.
                // Wait, if sum2 == 0, target2 = m. No sum1 is >= m.
                // If sum2 > 0, target2 < m.
            }

            // We want the smallest sum1 such that sum1 >= m - sum2.
            // If m - sum2 == 0, we want smallest sum1 >= 0.
            // If m - sum2 > 0, we want smallest sum1 >= m - sum2.

            int idx2 = Arrays.binarySearch(sums1, target2);
            if (idx2 < 0) {
                idx2 = -idx2 - 1; // Insertion point, which is the first element >= target2
            }
            if (idx2 < sums1.length) {
                long candidate = (sums1[idx2] + sum2) % m;
                if (candidate > maxMod) {
                    maxMod = candidate;
                }
            }
        }

        System.out.println(maxMod);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        long[] a = new long[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(st.nextToken());
        }

        int mid = n / 2;
        int n1 = mid;
        int n2 = n - mid;

        long[] arr1 = new long[n1];
        long[] arr2 = new long[n2];

        for (int i = 0; i < n1; i++) {
            arr1[i] = a[i];
        }
        for (int i = 0; i < n2; i++) {
            arr2[i] = a[mid + i];
        }

        List<Long> sums1 = generateSums(arr1, m);
        List<Long> sums2 = generateSums(arr2, m);

        Collections.sort(sums1);
        Collections.sort(sums2);

        long maxMod = 0;
        int size1 = sums1.size();
        int size2 = sums2.size();

        for (int i = 0; i < size1; i++) {
            long s1 = sums1.get(i);
            // We want to find s2 such that (s1 + s2) % m is maximized.
            // Let target = m - s1.
            // If we find s2 such that s2 % m is close to target (but < target), then (s1 + s2) % m = s1 + s2 - m (if s1+s2 >= m) or s1+s2 (if < m).
            // Actually, it's easier to think: we want (s1 + s2) % m.
            // Let x = s1 % m. We want y = s2 % m such that (x + y) % m is max.
            // The max possible value is m-1.
            // We can binary search in sums2 for the largest value < (m - x).
            // If we find such a value y, then (x + y) % m = x + y (since x+y < m).
            // Also consider the largest value in sums2 (which gives (x + y_max) % m).

            long target = m - s1;
            // Find the largest element in sums2 that is < target
            // If no such element, use the smallest element? No, we want to maximize the sum modulo m.
            // The candidates for s2 are:
            // 1. The largest s2 in sums2 such that s2 < target. Then (s1 + s2) % m = s1 + s2.
            // 2. The largest s2 in sums2 overall. Then (s1 + s2) % m = (s1 + s2) % m.

            // Binary search for target in sums2
            int lo = 0, hi = size2 - 1;
            int idx = -1;
            while (lo <= hi) {
                int midIdx = (lo + hi) / 2;
                if (sums2.get(midIdx) < target) {
                    idx = midIdx;
                    lo = midIdx + 1;
                } else {
                    hi = midIdx - 1;
                }
            }

            if (idx != -1) {
                long s2 = sums2.get(idx);
                long val = (s1 + s2) % m;
                if (val > maxMod) maxMod = val;
            }

            // Also check the largest element in sums2
            if (size2 > 0) {
                long s2_max = sums2.get(size2 - 1);
                long val = (s1 + s2_max) % m;
                if (val > maxMod) maxMod = val;
            }
        }

        System.out.println(maxMod);
    }

    private static List<Long> generateSums(long[] arr, long m) {
        int n = arr.length;
        List<Long> sums = new ArrayList<>();
        int total = 1 << n;
        for (int mask = 0; mask < total; mask++) {
            long sum = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += arr[i];
                }
            }
            sums.add(sum % m);
        }
        return sums;
    }
}

