public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        long m = Long.parseLong(st.nextToken());

        long[] a = new long[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(st.nextToken());
        }

        // Split the array into two halves
        int mid = n / 2;
        int n1 = mid;
        int n2 = n - mid;

        // Generate all possible subset sums modulo m for the first half
        List<Long> sums1 = new ArrayList<>();
        for (int mask = 0; mask < (1 << n1); mask++) {
            long sum = 0;
            for (int i = 0; i < n1; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum = (sum + a[i]) % m;
                }
            }
            sums1.add(sum);
        }

        // Sort the sums for binary search
        Collections.sort(sums1);

        // Generate all possible subset sums modulo m for the second half and find the best match
        long maxVal = 0;
        for (int mask = 0; mask < (1 << n2); mask++) {
            long sum = 0;
            for (int i = 0; i < n2; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum = (sum + a[mid + i]) % m;
                }
            }

            // We want to maximize (sum1 + sum2) % m
            // Let S = sum2. We need to find sum1 such that (sum1 + S) % m is maximized.
            // This is equivalent to finding the largest sum1 such that sum1 <= m - 1 - S
            // OR if no such sum1 exists, we take the largest sum1 overall (which will result in a wrap-around, 
            // but actually if sum1 + S >= m, the value is sum1 + S - m. 
            // Wait, the standard approach is:
            // We want to find x in sums1 such that (x + sum) % m is max.
            // Let target = m - 1 - sum.
            // If we find x <= target, then (x + sum) % m = x + sum. Maximize x.
            // If no x <= target exists, then for all x, x + sum >= m, so (x + sum) % m = x + sum - m.
            // To maximize this, we should maximize x. So we take the largest x in sums1.

            long target = m - 1 - sum;

            // Binary search for the largest element in sums1 <= target
            int lo = 0, hi = sums1.size() - 1;
            int bestIdx = -1;
            while (lo <= hi) {
                int midIdx = (lo + hi) / 2;
                if (sums1.get(midIdx) <= target) {
                    bestIdx = midIdx;
                    lo = midIdx + 1;
                } else {
                    hi = midIdx - 1;
                }
            }

            if (bestIdx != -1) {
                long candidate = (sums1.get(bestIdx) + sum) % m;
                if (candidate > maxVal) {
                    maxVal = candidate;
                }
            }

            // Also consider the case where we take the largest sum1 (wrap-around case)
            // Actually, if bestIdx is -1, it means all sums1 > target.
            // In that case, the best is the largest sum1.
            // But even if bestIdx != -1, it's possible that taking a larger sum1 (causing wrap) gives a better result?
            // No. If x <= target, x+sum < m. Value is x+sum.
            // If y > target, y+sum >= m. Value is y+sum-m.
            // Since y > target = m-1-sum, y+sum-m > -1.
            // Is it possible that y+sum-m > x+sum?
            // y+sum-m > x+sum => y - m > x => y > x + m.
            // Since x, y < m, x+m > m, but y < m. So y cannot be > x+m.
            // Thus, if there is an x <= target, the best non-wrapping sum is always better than any wrapping sum?
            // Let's check.
            // Max non-wrapping: x_max + sum where x_max is largest <= target.
            // Max wrapping: y_max + sum - m where y_max is largest overall.
            // We know x_max <= target = m - 1 - sum.
            // So x_max + sum <= m - 1.
            // y_max + sum - m. Since y_max < m, y_max + sum - m < sum.
            // Is sum > x_max + sum? No.
            // Wait.
            // Example: m=10, sum=2. target=7.
            // sums1 = {8, 9}.
            // No x <= 7. bestIdx = -1.
            // We take y_max = 9. (9+2)%10 = 1.
            // Example: m=10, sum=2. target=7.
            // sums1 = {5, 8}.
            // x_max = 5. (5+2)%10 = 7.
            // y_max = 8. (8+2)%10 = 0.
            // 7 > 0. So non-wrapping is better.
            // Example: m=10, sum=8. target=1.
            // sums1 = {2, 9}.
            // No x <= 1. bestIdx = -1.
            // y_max = 9. (9+8)%10 = 7.
            // Example: m=10, sum=8. target=1.
            // sums1 = {1, 9}.
            // x_max = 1. (1+8)%10 = 9.
            // y_max = 9. (9+8)%10 = 7.
            // 9 > 7.

            // So if bestIdx != -1, the candidate from bestIdx is the best for this 'sum'.
            // If bestIdx == -1, we must use the largest sum1.

            if (bestIdx == -1) {
                long candidate = (sums1.get(sums1.size() - 1) + sum) % m;
                if (candidate > maxVal) {
                    maxVal = candidate;
                }
            }
        }

        System.out.println(maxVal);
    }
}

