public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        long m = Long.parseLong(st.nextToken());

        long[] a = new long[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(st.nextToken());
        }

        // Split the array into two halves
        int mid = n / 2;
        int n1 = mid;
        int n2 = n - mid;

        // Generate all possible subset sums modulo m for the first half
        long[] sums1 = new long[1 << n1];
        for (int mask = 0; mask < (1 << n1); mask++) {
            long sum = 0;
            for (int i = 0; i < n1; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum = (sum + a[i]) % m;
                }
            }
            sums1[mask] = sum;
        }

        // Sort the first half sums
        Arrays.sort(sums1);

        // Generate all possible subset sums modulo m for the second half and find the best match
        long maxVal = 0;

        for (int mask = 0; mask < (1 << n2); mask++) {
            long sum2 = 0;
            for (int i = 0; i < n2; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum2 = (sum2 + a[mid + i]) % m;
                }
            }

            // We want to maximize (sum1 + sum2) % m
            // Let S = sum2. We want to find sum1 such that (sum1 + S) % m is maximized.
            // This is equivalent to finding sum1 such that sum1 + S is as close to m-1 as possible without exceeding it,
            // OR sum1 + S >= m and (sum1 + S) % m is as close to m-1 as possible.

            // Case 1: sum1 + sum2 < m
            // We want the largest sum1 such that sum1 <= m - 1 - sum2
            long target1 = (m - 1 - sum2 + m) % m;
            int idx1 = Arrays.binarySearch(sums1, target1);
            if (idx1 < 0) {
                idx1 = -idx1 - 1;
            }
            // Check the element at idx1 - 1 (largest <= target1)
            if (idx1 > 0) {
                long candidate = (sums1[idx1 - 1] + sum2) % m;
                if (candidate > maxVal) {
                    maxVal = candidate;
                }
            }

            // Case 2: sum1 + sum2 >= m
            // We want the smallest sum1 such that sum1 > m - 1 - sum2
            // This is equivalent to finding the smallest sum1 such that sum1 >= m - sum2
            // Actually, if sum1 + sum2 >= m, then (sum1 + sum2) % m = sum1 + sum2 - m.
            // To maximize this, we want to minimize sum1 + sum2 - m, which means minimizing sum1 + sum2 subject to sum1 + sum2 >= m.
            // So we want the smallest sum1 such that sum1 >= m - sum2.
            long target2 = m - sum2;
            // If sum2 is 0, target2 is m. But sums are in [0, m-1], so no sum1 can be >= m.
            // If sum2 > 0, target2 is in [1, m-1].
            if (target2 < m) {
                int idx2 = Arrays.binarySearch(sums1, target2);
                if (idx2 < 0) {
                    idx2 = -idx2 - 1;
                }
                // Check the element at idx2 (smallest >= target2)
                if (idx2 < sums1.length) {
                    long candidate = (sums1[idx2] + sum2) % m;
                    if (candidate > maxVal) {
                        maxVal = candidate;
                    }
                }
            }

            // Also consider the case where sum1 + sum2 could wrap around differently?
            // The logic above covers:
            // 1. Largest sum1 <= m-1-sum2 -> result < m
            // 2. Smallest sum1 >= m-sum2 -> result >= 0 (specifically sum1+sum2-m)

            // Wait, is it possible that the best sum1 is not the largest below or smallest above?
            // Let f(x) = (x + sum2) % m.
            // If x <= m-1-sum2, f(x) = x + sum2. This is increasing with x. So max is at largest x.
            // If x >= m-sum2, f(x) = x + sum2 - m. This is increasing with x. So min is at smallest x.
            // But we want to MAXIMIZE f(x).
            // In the second case, f(x) increases with x. So the maximum would be at the LARGEST x?
            // No, wait.
            // Let's re-evaluate.
            // We want max (x + S) % m.
            // Let y = x + S.
            // If y < m, value is y. Max y is m-1.
            // If y >= m, value is y - m. Max y is 2m-2 (since x, S < m). Value is m-2.
            // So values in [0, m-1] are possible.
            // The function (x+S) % m is not monotonic over the whole range of x.
            // It increases from S to m-1, then drops to 0, then increases to S-1.
            // So the maximum is either:
            // 1. The largest x such that x + S < m. (Value: x+S)
            // 2. The largest x overall? No.
            // Let's look at the shape.
            // x in [0, m-1].
            // x+S in [S, S+m-1].
            // (x+S)%m:
            // For x in [0, m-1-S], value is x+S. Max at x = m-1-S. Value = m-1.
            // For x in [m-S, m-1], value is x+S-m. Max at x = m-1. Value = S-1.
            // So the maximum is either m-1 (if there exists x such that x+S = m-1) or S-1 (if not, but wait, if m-1 is not achievable, the next best is m-2, etc.)

            // Actually, simply:
            // We want to find x in sums1 to maximize (x + S) % m.
            // This is equivalent to finding x such that x is as close to (m-1-S) % m as possible?
            // No.
            // Let's just check the two candidates derived from binary search:
            // Candidate A: Largest x <= (m-1-S) % m.
            // Candidate B: Smallest x >= (m-S) % m. (Note: if m-S == 0, this is 0. If m-S > 0, it's m-S).

            // Let's re-verify the "Smallest x >= m-S" logic.
            // If x >= m-S, then x+S >= m. Value = x+S-m.
            // This value increases as x increases.
            // So the MAXIMUM in this range is at the LARGEST x, i.e., x = m-1.
            // Value = (m-1 + S) % m = S - 1.
            // Is S-1 always better than the value from the first range?
            // The first range max is m-1 (if achievable).
            // If m-1 is not achievable, the max in first range is some value < m-1.
            // The max in second range is S-1.
            // So we should also check the largest x in the second range?
            // i.e., x = m-1?

            // Let's refine the candidates:
            // 1. Largest x such that x <= m-1-S. (If exists)
            // 2. Smallest x such that x >= m-S. (If exists) -> This gives the MINIMUM value in the wrap-around part.
            //    Wait, I want the MAXIMUM value.
            //    In the wrap-around part (x >= m-S), value = x + S - m.
            //    This is increasing with x. So the maximum is at the largest x, which is m-1.
            //    So candidate 2 should be: Largest x such that x >= m-S. Which is just the largest x in sums1 that is >= m-S.
            //    Actually, since sums1 is sorted, the largest x is sums1[last].
            //    But we need x >= m-S.
            //    So we can just check the largest element in sums1 that is >= m-S.
            //    Which is simply the last element if it's >= m-S, or we can find the upper bound.

            // Let's simplify.
            // We want max (x+S)%m.
            // This is max of:
            // a) max { x+S | x in sums1, x+S < m }
            // b) max { x+S-m | x in sums1, x+S >= m }

            // For a): We want max x such that x < m-S.
            //    Find largest x in sums1 < m-S.
            // For b): We want max x such that x >= m-S.
            //    Find largest x in sums1 >= m-S. (Which is just the largest x in sums1 if it satisfies the condition, or the largest one that does).

            // Let's implement this.

            // Reset maxVal for this sum2? No, maxVal is global.

            // Candidate 1: Largest x < m - sum2
            long limit1 = m - sum2;
            // We want x < limit1.
            // If limit1 <= 0, no such x exists (since x >= 0).
            if (limit1 > 0) {
                // Find largest x < limit1
                int idx = Arrays.binarySearch(sums1, limit1);
                if (idx < 0) {
                    idx = -idx - 1;
                }
                // idx is the first element >= limit1.
                // So idx-1 is the largest element < limit1.
                if (idx > 0) {
                    long x = sums1[idx - 1];
                    long val = (x + sum2) % m;
                    if (val > maxVal) maxVal = val;
                }
            }

            // Candidate 2: Largest x >= m - sum2
            // Note: if sum2 == 0, m - sum2 = m. No x >= m exists.
            if (sum2 > 0) {
                long limit2 = m - sum2;
                // Find smallest x >= limit2
                int idx = Arrays.binarySearch(sums1, limit2);
                if (idx < 0) {
                    idx = -idx - 1;
                }
                // idx is the first element >= limit2.
                // We want the LARGEST x >= limit2.
                // Since sums1 is sorted, the largest x is at the end of the array.
                // But we must ensure x >= limit2.
                // The largest x in sums1 is sums1[sums1.length - 1].
                // If sums1[sums1.length - 1] >= limit2, then it's a candidate.
                // Actually, any x >= limit2 is in the range [limit2, m-1].
                // The value is x + sum2 - m.
                // This is maximized when x is maximized.
                // So we just need the largest x in sums1 that is >= limit2.
                // Which is simply sums1[sums1.length - 1] if it is >= limit2.
                // Wait, is it possible that the largest x is < limit2?
                // If sums1[last] < limit2, then no x satisfies x >= limit2.
                if (sums1[sums1.length - 1] >= limit2) {
                    long x = sums1[sums1.length - 1];
                    long val = (x + sum2) % m;
                    if (val > maxVal) maxVal = val;
                }
            }
        }

        System.out.println(maxVal);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        long m = Long.parseLong(st.nextToken());

        st = new StringTokenizer(br.readLine());
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(st.nextToken());
        }

        // Meet in the middle approach
        // Split the array into two halves
        int mid = n / 2;

        // Generate all possible subset sums for the first half
        // There are 2^mid subsets
        long[] leftSums = new long[1 << mid];
        for (int mask = 0; mask < (1 << mid); mask++) {
            long sum = 0;
            for (int i = 0; i < mid; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += a[i];
                }
            }
            leftSums[mask] = sum % m;
        }

        // Sort the left sums to allow binary search
        Arrays.sort(leftSums);

        long maxVal = 0;

        // Generate all possible subset sums for the second half
        int rightSize = n - mid;
        for (int mask = 0; mask < (1 << rightSize); mask++) {
            long sum = 0;
            for (int i = 0; i < rightSize; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += a[mid + i];
                }
            }
            long rightSumMod = sum % m;

            // We want to maximize (leftSum + rightSum) % m
            // Let L = leftSum, R = rightSum
            // We want to maximize (L + R) % m
            // This is equivalent to finding L such that (L + R) % m is as large as possible.
            // Let target = m - R.
            // If we find an L such that L + R >= m, then (L + R) % m = L + R - m.
            // To maximize this, we want L + R to be as close to 2m - 1 as possible? No.
            // Actually, (L + R) % m is maximized when L + R is just below a multiple of m, or just below 2m.
            // Specifically, we want to find L such that (L + R) % m is max.
            // This happens if:
            // 1. L + R < m: then (L+R)%m = L+R. We want max L such that L < m - R.
            // 2. L + R >= m: then (L+R)%m = L+R-m. We want max L such that L < 2m - R.
            // Wait, L is in [0, m-1]. R is in [0, m-1].
            // So L+R is in [0, 2m-2].
            // (L+R)%m is:
            // L+R if L+R < m
            // L+R-m if L+R >= m

            // Case 1: L < m - R. Then result is L + R. Maximized by largest L < m - R.
            // Case 2: L >= m - R. Then result is L + R - m. Maximized by largest L (which is m-1) if m-1 >= m-R?
            // If we pick the largest possible L, say L_max, then result is L_max + R - m.
            // Is it better to pick L such that L+R is just below m?
            // Let's analyze.
            // We want to maximize (L+R) % m.
            // Let X = L+R.
            // If X < m, val = X.
            // If X >= m, val = X - m.

            // We can search for two candidates:
            // 1. Largest L such that L < m - R. (This makes L+R < m)
            //    Let idx1 = upper_bound(leftSums, m - R - 1). If idx1 >= 0, candidate1 = leftSums[idx1] + R.
            // 2. Largest L such that L < 2m - R. (This allows L+R to be up to 2m-2)
            //    Actually, we just want the largest L overall? No.
            //    If we take the largest L, L+R might be >= m. Then val = L+R-m.
            //    Is it possible that a smaller L gives a larger value?
            //    Suppose L1 < L2.
            //    If L2 + R < m, then val2 = L2+R > L1+R = val1. So larger L is better in this range.
            //    If L1 + R < m <= L2 + R.
            //    val1 = L1 + R.
            //    val2 = L2 + R - m.
            //    We want to know if val2 > val1.
            //    L2 + R - m > L1 + R  => L2 - L1 > m.
            //    But L2 < m and L1 >= 0, so L2 - L1 < m. Thus val2 < val1 is always true?
            //    Wait. L2 is at most m-1. L1 is at least 0.
            //    L2 - L1 <= m-1.
            //    So L2 + R - m <= L1 + R - 1.
            //    So val2 < val1.
            //    Therefore, if there exists an L such that L + R < m, the best value in that range is better than any value in the range L+R >= m?
            //    Let's check.
            //    Max value in range L+R < m is (m-1-R) + R = m-1 (if such L exists).
            //    Max value in range L+R >= m is (m-1) + R - m = R - 1.
            //    Since R >= 0, m-1 > R-1 (for m>1).
            //    So the maximum possible value is always achieved by making L+R < m, IF such an L exists.
            //    If no such L exists (i.e., all L >= m-R), then we must have L+R >= m.
            //    In that case, we want to maximize L+R-m. This is achieved by maximizing L.
            //    So we just pick the largest L.

            // So the strategy is:
            // 1. Find the largest L such that L < m - R.
            //    If found, candidate = L + R.
            // 2. Find the largest L (which is leftSums[last]).
            //    candidate2 = (leftSums[last] + R) % m.
            //    Actually, if L >= m-R, then (L+R)%m = L+R-m.
            //    We want to maximize this, so we pick the largest L.

            // Let's refine.
            // We want to maximize (L + R) % m.
            // Let target = m - R.
            // We look for L in leftSums.
            // If we find L such that L < target, then (L+R)%m = L+R.
            // To maximize this, we want the largest L < target.
            // If we find L such that L >= target, then (L+R)%m = L+R-m.
            // To maximize this, we want the largest L.

            // So:
            // 1. Binary search for the largest L < m - R.
            //    Let idx = upper_bound(leftSums, m - R - 1).
            //    If idx >= 0, candidate1 = leftSums[idx] + R.
            // 2. candidate2 = (leftSums[leftSums.length - 1] + R) % m.
            //    Note: if the largest L is < m-R, then candidate2 is the same as candidate1 (or smaller if we picked a smaller one? No, we picked largest < m-R for candidate1, and largest overall for candidate2. If largest overall < m-R, they are the same L).
            //    If the largest L >= m-R, then candidate1 might not exist (if all L >= m-R) or candidate1 uses a smaller L.
            //    In any case, we take max(candidate1, candidate2).

            long target = m - rightSumMod;
            // Find largest L < target
            // upper_bound finds first element > x. We want last element <= x.
            // So we search for x = target - 1.
            // If target == 0, then we want L < 0, which is impossible since L >= 0.

            int idx = -1;
            if (target > 0) {
                // Find first element >= target
                int lo = 0, hi = leftSums.length;
                while (lo < hi) {
                    int midIdx = (lo + hi) / 2;
                    if (leftSums[midIdx] < target) {
                        lo = midIdx + 1;
                    } else {
                        hi = midIdx;
                    }
                }
                // lo is the first index where leftSums[lo] >= target
                // So lo - 1 is the last index where leftSums[lo-1] < target
                if (lo > 0) {
                    idx = lo - 1;
                }
            }

            long cand1 = -1;
            if (idx != -1) {
                cand1 = leftSums[idx] + rightSumMod;
                // Since leftSums[idx] < m - rightSumMod, cand1 < m.
                // So cand1 % m = cand1.
            }

            long cand2 = (leftSums[leftSums.length - 1] + rightSumMod) % m;

            long currentMax = Math.max(cand1, cand2);
            if (currentMax > maxVal) {
                maxVal = currentMax;
            }
        }

        System.out.println(maxVal);
    }
}

