                    // But standard problem format puts them on one line. 
                    // If not enough tokens, try reading more lines.
                    // For robustness, let's assume standard format.
                    a[i] = 0; 
                }
            }
        }

        // Meet in the middle approach
        int mid = n / 2;
        int n1 = mid;
        int n2 = n - mid;

        // Generate all subset sums for the first half modulo m
        // We need to store unique values to optimize search, but n is small (35), so 2^17 is manageable.
        // 2^17 = 131072.

        long[] sums1 = new long[1 << n1];
        sums1[0] = 0;
        for (int i = 0; i < n1; i++) {
            long val = a[i] % m;
            for (int j = 0; j < (1 << i); j++) {
                sums1[(1 << i) + j] = (sums1[j] + val) % m;
            }
        }

        // Sort sums1 to allow binary search
        Arrays.sort(sums1);

        // Generate subset sums for the second half and check against sums1
        long best = 0;

        // Iterate through all subsets of the second half
        for (int mask = 0; mask < (1 << n2); mask++) {
            long sum2 = 0;
            for (int i = 0; i < n2; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum2 = (sum2 + a[mid + i]) % m;
                }
            }

            // We want to maximize (sum1 + sum2) % m
            // Let S = sum2. We want to find sum1 such that (sum1 + S) % m is maximized.
            // This is equivalent to finding sum1 such that sum1 is close to m - S.
            // Specifically, if we can find sum1 such that sum1 + S >= m, the result is (sum1 + S) - m.
            // If sum1 + S < m, the result is sum1 + S.

            // Case 1: sum1 + S < m. Maximize sum1 + S.
            // This means we want the largest sum1 < m - S.
            long target1 = m - sum2;
            // Find the largest element in sums1 that is < target1
            // If target1 is 0, we want largest < 0, which doesn't exist (sums are non-negative).
            // Actually, sums are in [0, m-1].

            // Binary search for the largest element < target1
            int idx = Arrays.binarySearch(sums1, target1);
            if (idx < 0) {
                idx = -idx - 2; // predecessor
            } else {
                // If exact match found, it's < target1? No, it's == target1.
                // If sum1 == m - sum2, then (sum1 + sum2) % m = 0.
                // We want strictly less than m - sum2 to get a positive remainder close to m.
                // Wait, if sum1 + sum2 == m, result is 0.
                // If sum1 + sum2 > m, result is sum1 + sum2 - m.
                // If sum1 + sum2 < m, result is sum1 + sum2.

                // Let's just check the candidates around the insertion point.
                // The candidates for sum1 are the ones that make sum1 + sum2 closest to m (from below or above).
                // Actually, the maximum value of (sum1 + sum2) % m is either:
                // 1. The largest sum1 such that sum1 + sum2 < m. Result: sum1 + sum2.
                // 2. The smallest sum1 such that sum1 + sum2 >= m. Result: sum1 + sum2 - m.

                // Let's find the largest sum1 < m - sum2.
                // And the smallest sum1 >= m - sum2.

                // Candidate 1: largest sum1 < m - sum2
                if (idx >= 0) {
                    long s1 = sums1[idx];
                    long res = (s1 + sum2) % m;
                    if (res > best) best = res;
                }

                // Candidate 2: smallest sum1 >= m - sum2
                // If idx found exact match, it's at idx.
                // If not, insertion point is -idx-1.
                int insertPos = (idx < 0) ? (-idx - 1) : idx;
                if (insertPos < sums1.length) {
                    long s1 = sums1[insertPos];
                    long res = (s1 + sum2) % m;
                    if (res > best) best = res;
                }
            }
        }

        System.out.println(best);
    }
}

