            // If we can find s2 such that s1 + s2 < m and s2 is close to target,
            // then (s1 + s2) % m = s1 + s2.
            // The best candidate is the largest s2 <= target.
            // If no such s2 exists, the best candidate is the smallest s2 (which will cause a wrap-around).

            long target = m - s1;

