        int m = Integer.parseInt(st.nextToken());

        st = new StringTokenizer(br.readLine());
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }

        int mid = n / 2;
        int n1 = mid;
        int n2 = n - mid;

        // Generate all subset sums for the first half
        List<Long> sums1 = new ArrayList<>();
        for (int mask = 0; mask < (1 << n1); mask++) {
            long sum = 0;
            for (int i = 0; i < n1; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += a[i];
                }
            }
            sums1.add(sum % m);
        }

        // Sort the first half sums
        Collections.sort(sums1);

        // Generate all subset sums for the second half and find max
        long max = 0;
        for (int mask = 0; mask < (1 << n2); mask++) {
            long sum = 0;
            for (int i = 0; i < n2; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += a[n1 + i];
                }
            }
            long s2 = sum % m;

            // We want to find s1 such that (s1 + s2) % m is maximized.
            // Let total = s1 + s2.
            // If total < m, result is total. We want total as close to m-1 as possible.
            // If total >= m, result is total - m. We want total - m as close to m-1 as possible,
            // which means total as close to 2m - 1 as possible.

            // Case 1: s1 + s2 < m
            // We want the largest s1 such that s1 < m - s2.
            long target1 = m - s2;
            // Find the largest element in sums1 that is < target1
            int idx1 = Collections.binarySearch(sums1, target1);
            if (idx1 < 0) {
                idx1 = -idx1 - 1;
            }
            if (idx1 > 0) {
                long candidate = (sums1.get(idx1 - 1) + s2) % m;
                if (candidate > max) max = candidate;
            }

            // Case 2: s1 + s2 >= m
            // We want the largest s1 such that s1 + s2 is as large as possible but < 2m.
            // Actually, we just want the largest s1 overall, because adding a larger s1
            // will make s1+s2 larger. If s1+s2 >= 2m, then (s1+s2)%m = s1+s2-2m.
            // But since s1 < m and s2 < m, s1+s2 < 2m. So s1+s2 is in [m, 2m).
            // The result is s1+s2-m. To maximize this, we maximize s1.
            // So we just take the largest s1 from sums1.
            // Wait, is it always optimal to take the largest s1 for the wrap-around case?
            // Yes, because (s1 + s2 - m) is increasing with s1.
            // So we just need the max element in sums1.
            // However, we must ensure that s1 + s2 >= m.
            // If the largest s1 + s2 < m, then this case doesn't apply.
            // But we already handled the case where s1 + s2 < m in Case 1.
            // So for Case 2, we just need to check if the largest s1 + s2 >= m.
            // If yes, the result is largest_s1 + s2 - m.

            long maxS1 = sums1.get(sums1.size() - 1);
            if (maxS1 + s2 >= m) {
                long candidate = (maxS1 + s2) % m;
                if (candidate > max) max = candidate;
            }
        }

        System.out.println(max);
    }
}

import java.util.*;
