public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        long[] a = new long[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(st.nextToken());
        }

        int mid = n / 2;
        int n1 = mid;
        int n2 = n - mid;

        List<Long> sums1 = new ArrayList<>();
        generateSums(a, 0, n1, 0, m, sums1);

        List<Long> sums2 = new ArrayList<>();
        generateSums(a, mid, n, 0, m, sums2);

        Collections.sort(sums1);
        Collections.sort(sums2);

        long maxMod = 0;

        for (long s2 : sums2) {
            long target = (m - s2 % m + m) % m;
            int idx = upperBound(sums1, target);
            if (idx > 0) {
                long candidate = (s2 + sums1.get(idx - 1)) % m;
                if (candidate > maxMod) {
                    maxMod = candidate;
                }
            }
            if (target == 0 && !sums1.isEmpty()) {
                 long candidate = (s2 + sums1.get(0)) % m;
                 if (candidate > maxMod) {
                     maxMod = candidate;
                 }
            }
        }

        System.out.println(maxMod);
    }

    static void generateSums(long[] a, int start, int end, long currentSum, long m, List<Long> sums) {
        if (start == end) {
            sums.add(currentSum % m);
            return;
        }
        generateSums(a, start + 1, end, currentSum, m, sums);
        generateSums(a, start + 1, end, currentSum + a[start], m, sums);
    }

    static int upperBound(List<Long> list, long target) {
        int low = 0;
        int high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) <= target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}

