            if (s1 + maxS2 >= m) {
                long candidate = (s1 + maxS2) % m;
                if (candidate > best) best = candidate;
            }

            // Also check the smallest s2 >= m - s1 (in case a smaller s2 gives a better result? No, larger s2 is better)
            // Actually the above covers it.
        }

        System.out.println(best);
    }

    // Returns the index of the first element >= target
    static int lowerBound(List<Long> list, long target) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid) < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}
